function createTimer(seconds) {
  return {
    seconds,
    add(more) {
      this.seconds += more;

      return this;
    },
  };
}

const egg = createTimer(60);
const softEgg = egg.add(120);
const hardEgg = softEgg.add(300);
const tea = createTimer(60).add(120);

console.log(softEgg.seconds);
console.log(egg === hardEgg);
console.log(tea.seconds);
console.log(tea === egg);
